Av={3:1,5:1,3411:1},QAv='Duplicate key ',RAv={1572:1,1992:1},SAv={1572:1,1992:1,11764:1},TAv={1572:1,1992:1,1759:1},UAv='Invalid UTF8 sequence',VAv='fromIndex: ',WAv=' > toIndex: ',XAv=', toIndex: ',YAv='Index: ',ZAv=', Size: ',$Av=36161,_Av='u_GlowColor',aBv='u_GlowOffset',bBv='u_GlowWidth',cBv='u_GlowSoftness',dBv='u_GlowTextureAlphaLimitValue',eBv='u_BorderWidth',fBv='u_BorderColor',gBv='u_BaseSmoothing',hBv='// SHADER\n#ifdef GL_ES\n//precision lowp float;\nprecision mediump float;\n#else\n// Not all versions of regular OpenGL supports precision qualifiers, define placeholders\n#define lowp\n#define mediump\n#define highp\n#endif\n\nvarying vec4 v_Color;\nvarying vec2 v_TexCoord;\nvarying vec2 v_TexSize;\nvarying float v_VerScale;\n\nuniform sampler2D u_Texture;\n\nuniform float u_BaseSmoothing;// 1 - 4\n\nuniform vec4 u_GlowColor;// RGBA\nuniform vec2 u_GlowOffset;// pixels\nuniform float u_GlowWidth;// 0.0 - 1.0\nuniform float u_GlowSoftness;// 0.0 - border; 1.0 gradient\n// parametr okreslajacy kiedy ma sie rysowac glow. Dodalismy ten parametr po to by glow nie byl rysowany pod tekstura, tylko zaczal sie rysowac wokol tekstury.\n// Jako ze nie wiadomo jak to policzyc ustawiamy to z parametru\nuniform float u_GlowTextureAlphaLimitValue;\n\nuniform float u_BorderWidth;// = 0.0;\nuniform vec4 u_BorderColor;// RGBA\n\nuniform int u_IsBold;// 0 or 1\n\nconst float THRESHOLD = 0.5;\nconst float BOLD_THRESHOLD = 0.8;\n\nvoid main() {\n    float smoothing = u_BaseSmoothing / (16.0 * v_VerScale);\n    vec4 texColor = texture2D(u_Texture, v_TexCoord);\n    float dst = texColor.a;\n    if (u_IsBold == 1) {\n        dst = smoothstep(0.0, BOLD_THRESHOLD, dst);\n    }\n\n    // Soft edges\n    float alpha = smoothstep(THRESHOLD - smoothing, (1.0 - THRESHOLD) + smoothing, dst);\n    vec4 color = v_Color * vec4(1.0, 1.0, 1.0, alpha);\n\n    if (u_GlowWidth > 0.0 && u_GlowColor.a > 0.0) {\n        if (texColor.a <= u_GlowTextureAlphaLimitValue) {\n//            color = mix(u_GlowColor, color, color.a);\n            float glowMin = clamp(THRESHOLD - (u_GlowWidth * THRESHOLD), 0.01, THRESHOLD);\n            float glowMax = clamp(THRESHOLD * u_GlowSoftness, glowMin, THRESHOLD * 2.0);\n            vec2 glowOffset = vec2(u_GlowOffset.x / v_TexSize.x, u_GlowOffset.y / v_TexSize.y);\n            float glowDst = texture2D(u_Texture, v_TexCoord + glowOffset).a;\n            if (u_IsBold == 1) {\n                glowDst = smoothstep(0.0, BOLD_THRESHOLD, glowDst);\n            }\n            vec4 glowColor = vec4(u_GlowColor.rgb, u_GlowColor.a * v_Color.a);\n            vec4 glow = vec4(glowColor.rgb, smoothstep(glowMin, glowMax, glowDst) * glowColor.a);\n            color = mix(glow, color, alpha);\n        }\n    }\n\n    if (u_BorderWidth > 0.0) {\n        float borderMin = clamp(THRESHOLD - (u_BorderWidth * THRESHOLD), 0.01, THRESHOLD);\n        float borderMax = THRESHOLD;\n\n        if (dst > borderMin && dst < borderMax) {\n            float oFactor = 1.0;\n            if (dst < (borderMin + 0.05)) {\n                oFactor = smoothstep(borderMin, borderMin + 0.05, dst);\n            } else if (dst > (borderMax - 0.05)) {\n                oFactor = smoothstep(borderMax, borderMax - 0.05, dst);\n            }\n            vec4 borderColor = vec4(u_BorderColor.rgb, u_BorderColor.a * v_Color.a);\n            color = mix(color, borderColor, oFactor);\n        }\n    }\n\n    gl_FragColor = color;\n}\n',iBv='varying vec2 v_TexCoord;\nvarying vec4 v_Color;\nvarying float v_VerScale;\nvarying vec2 v_TexSize;\n',jBv='Win_Out',kBv='Win_Loop',lBv=-1080,mBv='s777d_logo_deluxe',nBv='s777d_winline_base',oBv='minitab',pBv='s7_bigwin_bgd.json',qBv='s7_bigwin_comets1.json',rBv='s7_bigwin_orangestar1.json',sBv='s7_bigwin_stardust.json',tBv='s7_bigwin.json',uBv='s7_superwin_bgd.json',vBv='s7_superwin_orangestar.json',wBv='s7_superwin_stardust.json',xBv='s7_superwin.json',yBv='s7_megawin_bgd.json',zBv='s7_megawin_comets.json',ABv='s7_megawin_orangestar.json'